from PIL import Image
import numpy as np
im=np.array(Image.open('/app/target.png').convert('L'))<100
ys,xs=np.where(im)
print('bbox',xs.min(),xs.max(),ys.min(),ys.max(),'n',len(xs))
# components bfs
m=im[430:580,320:710]
H,W=m.shape; seen=np.zeros_like(m,bool); comps=[]
for yy,xx in zip(*np.where(m)):
 if not seen[yy,xx]:
  st=[(yy,xx)]; seen[yy,xx]=1; pix=[]
  while st:
   y,x=st.pop();pix.append((y,x))
   for dy in [-1,0,1]:
    for dx in [-1,0,1]:
     ny,nx=y+dy,x+dx
     if 0<=ny<H and 0<=nx<W and m[ny,nx] and not seen[ny,nx]:seen[ny,nx]=1;st.append((ny,nx))
  yy0=min(p[0] for p in pix)+430; yy1=max(p[0] for p in pix)+430; xx0=min(p[1] for p in pix)+320; xx1=max(p[1] for p in pix)+320
  comps.append((xx0,yy0,xx1,yy1,len(pix)))
print('components',sorted(comps,key=lambda a:(a[1],a[0])))
for y in [460,470,480,490,500,510,520,530,540,550,560]:
 runs=[]; on=False
 for x in range(300,720):
  b=im[y,x]
  if b and not on:a=x;on=1
  if on and (not b or x==719):
   e=x-1 if not b else x
   if e-a>=2:runs.append((a,e))
   on=0
 print(y,runs)
